def check_scenario(scenario, liar_count, statements, days_of_week):
    # Check if the scenario is consistent with the statements
    # by verifying that all statements made by non-criminals
    # are consistent with the scenario, and all statements
    # made by criminals are not consistent with the scenario.
    for participant, statements_list in statements.items():
        if participant != scenario:
            # Verify that the statements made by non-criminals
            # are consistent with the scenario
            for statement in statements_list:
                if statement not in days_of_week:
                    return False
        else:
            # Verify that the statements made by the criminal
            # are not consistent with the scenario
            for statement in statements_list:
                if statement in days_of_week:
                    return False
    return True

